files = ['router.py','client.py','parser.py','auth.py','schema.py','search.py','lexer.py','server.py','index.py','eval.py','logger.py','worker.py','queue.py','billing.py']
results = {}
for f in files:
    results[f] = git_last_commit(f)

# collect Yara Haddad files
pairs = []
for f in files:
    if results[f]['author'] == 'Yara Haddad':
        pairs.append((f, results[f]['commit']))

created = 0
for f, commit in pairs:
    tag = 'review-' + f[:-3]
    git_create_tag(tag, commit)
    created += 1

print(created)

pkgs = ['idna','urllib3','boto3','pyyaml','rich','scipy','sqlalchemy','wheel','pydantic','pip','pytest','matplotlib','httpx','django','flask','pandas']
vals = []
for p in pkgs:
    for _ in range(3):
        try:
            r = pypi_package(p)
            vals.append((p, r['version']))
            break
        except ToolError:
            pass
print('\n'.join([f"{p} {v}" for p,v in vals]))

